import{_ as o,o as e,c as d,a as r}from"./app.83c7065c.js";const A=JSON.parse('{"title":"Android模拟器访问本地web服务的url","description":"","frontmatter":{"title":"Android模拟器访问本地web服务的url","date":"2018-03-29"},"headers":[],"relativePath":"2018/android-emulator-localhost-url.md","lastUpdated":1786184870000}'),t={name:"2018/android-emulator-localhost-url.md"},c=r('<p>不会自己搭<code>mock server</code>的前端不是好前端。<br> 后台开发和前端开发不能完全实现同步，一直停下等后台是要出问题的。 于是基于<code>json-server</code>搭了一个 API 本地测试服务器，却遇到了一个莫名其妙但极其简单的问题，简单记录一下，避免以后二次踩坑。</p><blockquote><h3 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-hidden="true">#</a></h3><p><strong>Android 模拟器访问本地服务器，把 url 设置成<code>10.0.2.2</code>或者本机 IP 地址</strong><br><strong>Android 真机访问本地服务器，同一个局域网内，把 url 设置成本机 IP 地址</strong></p></blockquote><ol><li><p>踩坑<br> 使用<code>Android</code>模拟器访问<code>mock server</code>的时候发现使用<code>http://localhost:3000</code>的默认配置怎么都取不到数据。 查了无数遍<code>http</code>包头、API 返回的<code>response</code>，一无所获。 过了老半天才恍然大悟，<code>Android</code>本来就是一个系统，自己也是有<code>ip</code>地址的，本机运行的时候应该<strong>设置成<code>Android</code>内置的地址<code>http://10.0.2.2:3000</code></strong></p></li><li><p>进阶试验<br> 然后想到了一个问题，<code>Android</code>模拟器和本机在同一个局域网内，那么<code>url</code>改成本机的 IP 地址，应该也是可以访问的。 测试果然可行，这个方法适合<code>Android</code>真机调试。</p></li></ol>',3),a=[c];function n(s,l,i,_,p,h){return e(),d("div",null,a)}const m=o(t,[["render",n]]);export{A as __pageData,m as default};
